		sys, err := NewDescriptor(mat.NewDense(tc.n, tc.n, tc.a), mat.NewDense(tc.n, tc.m, tc.b), mat.NewDense(tc.p, tc.n, tc.c), mat.NewDense(tc.p, tc.m, tc.d), mat.NewDense(tc.n, tc.n, tc.e), 0)
